response.text:
{
  "title": "HCV Adherence Challenge",
  "perWatchSecond": 1,
  "levels": [
    {
      "kind": "hook",
      "title": "The Spread of HCV",
      "goal": "Observe how the virus spreads when treatment adherence is low.",
      "control": {
        "parameter": "beta1",
        "label": "Acute transmission rate",
        "lowEnd": "0.1",
        "highEnd": "0.3"
      },
      "watch": "i",
      "whatIf": {
        "prompt": "What if the initial number of acutely infected people was higher?",
        "parameter": "i0",
        "value": 0.05
      },
      "difference": {
        "compartment": "i",
        "summary": "at",
        "at": 0.05,
        "time": 20,
        "relation": "higher",
        "by": 0.01
      },
      "effect": "The acutely infected population is higher by more than 0.01 at year 20.",
      "prediction": {
        "prompt": "Will more initial infections lead to more acute cases at year 20?",
        "claimed": "Yes",
        "other": "No"
      },
      "passage": {
        "title": "Context",
        "quote": "Hepatitis C virus (HCV) prevalence is still increasing in Zimbabwe"
      },
      "carryForward": ""
    },
    {
      "kind": "idea",
      "title": "The Power of Adherence",
      "goal": "See how increasing the proportion of people who stick to treatment affects the epidemic.",
      "control": {
        "parameter": "theta",
        "label": "Treatment adherence proportion",
        "lowEnd": "0.1",
        "highEnd": "0.9"
      },
      "watch": "i",
      "whatIf": {
        "prompt": "What if adherence exceeds the critical threshold of 52%?",
        "parameter": "theta",
        "value": 0.6
      },
      "difference": {
        "compartment": "i",
        "summary": "at",
        "at": 0.001,
        "time": 100,
        "relation": "lower",
        "by": 0.001
      },
      "effect": "The acutely infected population is lower by more than 0.001 at year 100.",
      "prediction": {
        "prompt": "Will adherence above 52% reduce the number of acute infections?",
        "claimed": "Yes",
        "other": "No"
      },
      "passage": {
        "title": "Adherence Threshold",
        "quote": "an adherence level exceeding 52% causes the reproduction number to drop below 1, curtailing further spread."
      },
      "carryForward": ""
    },
    {
      "kind": "result",
      "title": "The Risk of Quitting",
      "goal": "Understand why quitting treatment increases the spread of the virus.",
      "control": {
        "parameter": "delta",
        "label": "Treatment quitting rate",
        "lowEnd": "0.1",
        "highEnd": "0.9"
      },
      "watch": "cq",
      "whatIf": {
        "prompt": "What if the transmission rate of those who quit was halved?",
        "parameter": "beta3",
        "value": 0.025
      },
      "difference": {
        "compartment": "cq",
        "summary": "total",
        "at": 0.01,
        "time": 80,
        "relation": "lower",
        "by": 0.001
      },
      "effect": "The total number of people who quit treatment is lower by more than 0.001 over 80 years.",
      "prediction": {
        "prompt": "Will lowering the transmissibility of quitters reduce the overall burden?",
        "claimed": "Yes",
        "other": "No"
      },
      "passage": {
        "title": "Quitting Impact",
        "quote": "quitting treatment before reaching sustained viral response (SVR) increases HCV viral load, leading to higher transmissibility"
      },
      "carryForward": ""
    }
  ],
  "limits": [
    "Time is measured in years.",
    "Population proportions sum to 1."
  ]
}
